-- VERIFICACIÓN POSTERIOR de NEX-071. SOLO LECTURA. Cada fila debe dar ok = true. La ejecuta el responsable en la VM INMEDIATAMENTE después de aplicar la migración:
--   docker exec -i nexit-db psql -U nexit_app -d nexit -v ON_ERROR_STOP=1 < verificar-NEX-071.sql
BEGIN READ ONLY;
SELECT 'tabla nce_observaciones_originales existe y está vacía al aplicar' AS control, to_regclass('public.nce_observaciones_originales') IS NOT NULL AND (SELECT count(*) FROM public.nce_observaciones_originales) = 0 AS ok
UNION ALL SELECT 'PK (empresa, nce) y FK compuesta a nce_origen (empresa, nce)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.nce_observaciones_originales'::regclass AND contype = 'p') AND EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.nce_observaciones_originales'::regclass AND contype = 'f' AND confrelid = 'public.nce_origen'::regclass)
UNION ALL SELECT 'tabla de solo altas (disparadores de fila y TRUNCATE)', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'public.nce_observaciones_originales'::regclass AND NOT tgisinternal AND tgname LIKE 'nce_observaciones_originales_inmutable%') = 2
UNION ALL SELECT 'fe_documento_crear_nce_obs existe, SECURITY DEFINER y search_path fijo', EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = 'public.fe_documento_crear_nce_obs(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb,text)'::regprocedure AND p.prosecdef AND p.proconfig::text LIKE '%search_path%')
UNION ALL SELECT 'fe_documento_crear_nce (11 parámetros) sigue intacta y SECURITY DEFINER', EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure AND p.prosecdef) AND (SELECT prosrc FROM pg_proc WHERE oid = 'public.fe_documento_crear_nce(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb)'::regprocedure) LIKE '%nce_descuentos%'
UNION ALL SELECT 'el rol de la aplicación LEE la tabla pero no la escribe, y ejecuta la función nueva', has_table_privilege('nexit_runtime', 'public.nce_observaciones_originales', 'SELECT') AND NOT (has_table_privilege('nexit_runtime', 'public.nce_observaciones_originales', 'INSERT') OR has_table_privilege('nexit_runtime', 'public.nce_observaciones_originales', 'UPDATE') OR has_table_privilege('nexit_runtime', 'public.nce_observaciones_originales', 'DELETE')) AND has_function_privilege('nexit_runtime', 'public.fe_documento_crear_nce_obs(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb,text)', 'EXECUTE')
UNION ALL SELECT 'PUBLIC no ejecuta fe_documento_crear_nce_obs', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE p.oid = 'public.fe_documento_crear_nce_obs(uuid,uuid,uuid,uuid,text,uuid,integer,jsonb,text,numeric,jsonb,text)'::regprocedure AND a.grantee = 0);
ROLLBACK;
